#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<ll> a(N), b(N);
    for (int i = 0; i < N; ++i) cin >> a[i];
    for (int i = 0; i < N; ++i) cin >> b[i];

    // Key observation:
    // If b[i] = a[(i+k)%N] xor x for all i,
    // then for every i:
    // b[i] xor b[(i+1)%N] = a[(i+k)%N] xor a[(i+k+1)%N]
    //
    // Define:
    // da[i] = a[i] xor a[(i+1)%N]
    // db[i] = b[i] xor b[(i+1)%N]
    //
    // Then db must be a rotation of da by k.
    // After finding such k, x is uniquely determined by:
    // x = a[k] xor b[0]

    if (N == 1) {
        // For N=1, any k in [0,0] only, and x = a[0] xor b[0].
        cout << 0 << ' ' << (a[0] ^ b[0]) << '\n';
        return 0;
    }

    vector<ll> da(N), db(N);
    for (int i = 0; i < N; ++i) {
        da[i] = a[i] ^ a[(i + 1) % N];
        db[i] = b[i] ^ b[(i + 1) % N];
    }

    // KMP to find all occurrences of db in da+da.
    vector<ll> text(2 * N);
    for (int i = 0; i < 2 * N; ++i) text[i] = da[i % N];

    vector<int> pi(N, 0);
    for (int i = 1; i < N; ++i) {
        int j = pi[i - 1];
        while (j > 0 && db[i] != db[j]) j = pi[j - 1];
        if (db[i] == db[j]) ++j;
        pi[i] = j;
    }

    vector<pair<int, ll>> ans;
    int j = 0;
    for (int i = 0; i < 2 * N - 1; ++i) { // enough to cover all N rotations
        while (j > 0 && text[i] != db[j]) j = pi[j - 1];
        if (text[i] == db[j]) ++j;
        if (j == N) {
            int start = i - N + 1;
            if (start < N) {
                int k = start;
                ll x = a[k] ^ b[0];
                ans.push_back({k, x});
            }
            j = pi[j - 1];
        }
    }

    sort(ans.begin(), ans.end());
    for (auto &[k, x] : ans) {
        cout << k << ' ' << x << '\n';
    }

    return 0;
}

import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    a = list(map(int, input_data[1:1+n]))
    b = list(map(int, input_data[1+n:1+2*n]))

    results = []

    for k in range(n):
        x = a[k] ^ b[0]
        ok = True
        for i in range(1, n):
            if a[(i + k) % n] ^ x != b[i]:
                ok = False
                break
        if ok:
            results.append((k, x))

    out_lines = [f"{k} {x}" for k, x in results]
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

