import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[] a = new int[N];
        int[] b = new int[N];

        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            b[i] = Integer.parseInt(st.nextToken());
        }

        // Build difference arrays (XOR difference)
        int[] diffA = new int[N];
        int[] diffB = new int[N];
        for (int i = 0; i < N; i++) {
            diffA[i] = a[i] ^ a[(i + 1) % N];
            diffB[i] = b[i] ^ b[(i + 1) % N];
        }

        // Double diffA for pattern matching
        int[] doubled = new int[2 * N];
        for (int i = 0; i < N; i++) {
            doubled[i] = diffA[i];
            doubled[i + N] = diffA[i];
        }

        // KMP failure function on pattern diffB
        int[] fail = new int[N];
        for (int i = 1, j = 0; i < N; i++) {
            while (j > 0 && diffB[i] != diffB[j]) j = fail[j - 1];
            if (diffB[i] == diffB[j]) fail[i] = ++j;
        }

        // Search doubled for diffB
        List<Integer> matches = new ArrayList<>();
        for (int i = 0, j = 0; i < 2 * N - 1; i++) {
            while (j > 0 && doubled[i] != diffB[j]) j = fail[j - 1];
            if (doubled[i] == diffB[j]) j++;
            if (j == N) {
                matches.add(i - N + 1);
                j = fail[j - 1];
            }
        }

        // For each matched k, compute x and verify
        List<int[]> results = new ArrayList<>();
        for (int k : matches) {
            int x = b[0] ^ a[k];
            boolean ok = true;
            for (int i = 0; i < N; i++) {
                if ((a[(i + k) % N] ^ x) != b[i]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                results.add(new int[]{k, x});
            }
        }

        results.sort((p1, p2) -> {
            if (p1[0] != p2[0]) return Integer.compare(p1[0], p2[0]);
            return Integer.compare(p1[1], p2[1]);
        });

        StringBuilder sb = new StringBuilder();
        sb.append(results.size()).append("\n");
        for (int[] pair : results) {
            sb.append(pair[0]).append(" ").append(pair[1]).append("\n");
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int[] buildLPS(int[] p) {
        int m = p.length;
        int[] lps = new int[m];
        for (int i = 1, len = 0; i < m; ) {
            if (p[i] == p[len]) {
                lps[i++] = ++len;
            } else if (len > 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
            }
        }
        return lps;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int N = fs.nextInt();
        int[] a = new int[N];
        int[] b = new int[N];

        for (int i = 0; i < N; i++) a[i] = fs.nextInt();
        for (int i = 0; i < N; i++) b[i] = fs.nextInt();

        if (N == 1) {
            out.append(0).append(' ').append(a[0] ^ b[0]).append('\n');
            System.out.print(out);
            return;
        }

        // Define difference arrays by XOR of adjacent elements.
        // If a' is rotation of a by k and then all XOR x, adjacent XOR differences remain unchanged.
        // So we need to find k such that:
        // da rotated by k == db
        int[] da2 = new int[2 * (N - 1)];
        int[] db = new int[N - 1];

        for (int i = 0; i < N - 1; i++) {
            da2[i] = a[i] ^ a[i + 1];
            db[i] = b[i] ^ b[i + 1];
        }
        // cyclic edge
        int lastA = a[N - 1] ^ a[0];
        int lastB = b[N - 1] ^ b[0];

        // Full cyclic difference arrays of length N
        int[] ca2 = new int[2 * N];
        int[] cb = new int[N];
        for (int i = 0; i < N - 1; i++) {
            cb[i] = db[i];
            ca2[i] = da2[i];
        }
        cb[N - 1] = lastB;
        ca2[N - 1] = lastA;
        for (int i = 0; i < N; i++) {
            ca2[i + N] = ca2[i];
        }

        // KMP: find all occurrences of cb in ca2, starting positions < N
        int[] lps = buildLPS(cb);
        for (int i = 0, j = 0; i < 2 * N - 1; ) {
            if (ca2[i] == cb[j]) {
                i++;
                j++;
                if (j == N) {
                    int start = i - N;
                    if (start < N) {
                        int k = start;
                        int x = a[k] ^ b[0];
                        out.append(k).append(' ').append(x).append('\n');
                    }
                    j = lps[j - 1];
                }
            } else if (j > 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }

        System.out.print(out);
    }
}
